public final class AuditNavigationTest {
 AuditPhoneFixture f;
 @Before public void setup()throws Exception{f=new AuditPhoneFixture();List<JSONObject> items=new ArrayList<>();for(String prefix:new String[]{"Amber","Blue"})for(int n=0;n<170;n++)items.add(new JSONObject().put("id",prefix+n).put("group",prefix+n).put("title",String.format(Locale.ROOT,"%s %03d",prefix,n)).put("movie",true).put("inLibrary",true).put("listed",true).put("year",2020));f.data.rememberPhoneItems(items);}
 @After public void cleanup()throws Exception{if(f!=null)f.close();}
 EditText query(MainActivity a){return (EditText)AuditPhoneFixture.find(a.body,v->v instanceof EditText);}
 List<View> cards(MainActivity a){return AuditPhoneFixture.all(a.body,v->v.getContentDescription()!=null&&v.getContentDescription().toString().endsWith(" · "+Loc.t("Details")));}
 void more(MainActivity a){View v=AuditPhoneFixture.find(a.body,x->x instanceof TextView&&((TextView)x).getText().toString().startsWith(Loc.t("Show more")+" · "));assertNotNull("Show more is rendered",v);assertTrue(v.performClick());}
 String first(MainActivity a){for(View card:cards(a))if(AuditPhoneFixture.visible(card))return card.getContentDescription().toString();return "";}
 @Test public void libraryExpandedSearchSurvivesDetailRecreationAndKeepsQueriesSeparate()throws Exception{
  MainActivity a=f.launch(MainActivity.class);f.ui(()->{a.page="Library";a.render();AuditPhoneFixture.click(a.body,"My List");AuditPhoneFixture.click(a.body,"Movies");query(a).setText("Amber");more(a);more(a);assertEquals(144,cards(a).size());});f.idle();
  f.ui(()->a.scroller.scrollTo(0,a.dp(1700)));f.idle();int[] amberY={0};String[] amberTitle={""};f.ui(()->{amberY[0]=a.scroller.getScrollY();amberTitle[0]=first(a);assertTrue("Starting offset must be nonzero",amberY[0]>0);assertFalse(amberTitle[0].isEmpty());query(a).setText("Blue");});f.idle();
  f.ui(()->{assertEquals(48,cards(a).size());more(a);a.scroller.scrollTo(0,a.dp(900));});f.idle();int[] blueY={0};String[] blueTitle={""};f.ui(()->{blueY[0]=a.scroller.getScrollY();blueTitle[0]=first(a);assertTrue(blueY[0]>0);assertFalse(blueTitle[0].isEmpty());query(a).setText("Amber");});f.idle();
  f.ui(()->{assertEquals(144,cards(a).size());assertEquals(amberY[0],a.scroller.getScrollY());assertEquals(amberTitle[0],first(a));View card=cards(a).stream().filter(AuditPhoneFixture::visible).findFirst().orElseThrow();assertTrue(card.performClick());assertFalse(a.detail.isEmpty());});f.idle();
  MainActivity restored=f.recreate(a);f.ui(()->{assertFalse(restored.detail.isEmpty());restored.onBackPressed();});f.idle();
  f.ui(()->{assertEquals("Amber",query(restored).getText().toString());assertEquals("My List",restored.premium.collection);assertEquals("Movies",restored.homeLayout.libraryType);assertEquals(144,cards(restored).size());assertEquals(amberY[0],restored.scroller.getScrollY());assertEquals(amberTitle[0],first(restored));query(restored).setText("Blue");});f.idle();
  f.ui(()->{assertEquals(96,cards(restored).size());assertEquals(blueY[0],restored.scroller.getScrollY());assertEquals(blueTitle[0],first(restored));});
 }
 @Test public void allTransientFiltersAndDetailSeasonSurviveRecreation()throws Exception{
  List<JSONObject> show=new ArrayList<>();for(int s=1;s<=3;s++)show.add(new JSONObject().put("id","state-s"+s).put("group","state-show").put("title","State show").put("season",s).put("episode",1));f.data.rememberPhoneItems(show);f.data.phoneSetting("historyOnly",true);
  MainActivity a=f.launch(MainActivity.class);f.ui(()->{a.premium.hideLogged=true;a.premium.historyView="Diary";a.premium.month="2025-01";a.premium.status="Finished";a.premium.type="Shows";a.premium.sort="A–Z";a.premium.diaryLimit=180;a.homeLayout.smartFilter=SmartLists.IDS[0];a.homeLayout.plannedOnly=true;a.tracker.showsFilter="Watching";a.tracker.month=java.time.LocalDate.of(2025,1,1);a.tracker.day=java.time.LocalDate.of(2025,1,12);a.open(show.get(0));a.detailSeason=3;a.render();});f.idle();
  MainActivity b=f.recreate(a);f.ui(()->{assertEquals(3,b.detailSeason);assertTrue(b.premium.hideLogged);assertEquals("Diary",b.premium.historyView);assertEquals("2025-01",b.premium.month);assertEquals("Finished",b.premium.status);assertEquals("Shows",b.premium.type);assertEquals("A–Z",b.premium.sort);assertEquals(180,b.premium.diaryLimit);assertEquals(SmartLists.IDS[0],b.homeLayout.smartFilter);assertTrue(b.homeLayout.plannedOnly);assertEquals("Watching",b.tracker.showsFilter);assertEquals(java.time.LocalDate.of(2025,1,12),b.tracker.day);});
 }
 @Test public void discoverCachedBrowseRetainsExpansionOffsetAndSeason()throws Exception{
  DiscoverActivity a=f.launch(new Intent(f.test.getTargetContext(),DiscoverActivity.class).putExtra("title","{}"));String name="N3 "+UUID.randomUUID();JSONArray metas=new JSONArray();String id="tt"+Math.abs(System.nanoTime());for(int n=0;n<100;n++)metas.put(new JSONObject().put("id",n==0?id:id+n).put("name",name+" "+n).put("noirType","series"));JSONArray episodes=new JSONArray();for(int s=1;s<=3;s++)for(int e=1;e<=4;e++)episodes.put(new JSONObject().put("season",s).put("episode",e).put("name","Episode "+e));JSONObject seed=metas.getJSONObject(0),details=new JSONObject(seed.toString()).put("videos",episodes);
  String other=name+" other";for(String q:new String[]{name,other})f.cache(a.client,"catalog/series/top/search="+java.net.URLEncoder.encode(q,"UTF-8").replace("+","%20")+".json",new JSONObject().put("metas",metas));f.cache(a.client,"meta/series/"+id+".json",new JSONObject().put("meta",details));
  f.ui(()->{a.getIntent().removeExtra("title");if(a.current!=null)a.current.cancel(true);a.query=name;a.filter="TV shows";a.browse();a.find();});f.until(()->!a.loading&&a.shown==20);
  f.ui(()->{AuditPhoneFixture.clickPrefix(a.results,"Show more · ");AuditPhoneFixture.clickPrefix(a.results,"Show more · ");assertEquals(60,a.shown);});f.idle();f.ui(()->a.scroll.scrollTo(0,a.dp(1300)));f.idle();int[] y={0};String[] visible={""};
  f.ui(()->{y[0]=a.scroll.getScrollY();visible[0]=discoverFirst(a);assertTrue(y[0]>0);assertFalse(visible[0].isEmpty());a.open(seed);});f.until(()->!a.loading&&a.title!=null&&a.title.has("videos"));f.ui(()->{Spinner picker=(Spinner)AuditPhoneFixture.find(a.body,v->v instanceof Spinner);assertNotNull(picker);picker.setSelection(2);});f.until(()->a.season==3);
  DiscoverActivity b=f.recreate(a);f.until(()->!b.loading&&b.title!=null&&b.title.has("videos"));f.ui(()->{assertEquals(3,b.season);b.onBackPressed();});f.until(()->!b.loading&&b.shown==60);f.idle();f.ui(()->{assertEquals(name,b.search.getText().toString());assertEquals("TV shows",b.filter);assertEquals(60,b.shown);assertEquals(y[0],b.scroll.getScrollY());assertEquals(visible[0],discoverFirst(b));b.search.setText(other);});f.until(()->!b.loading&&b.shown==20);
  f.ui(()->AuditPhoneFixture.clickPrefix(b.results,"Show more · "));f.idle();f.ui(()->b.scroll.scrollTo(0,b.dp(700)));f.idle();int[] otherY={0};String[] otherTitle={""};f.ui(()->{otherY[0]=b.scroll.getScrollY();otherTitle[0]=discoverFirst(b);assertTrue(otherY[0]>0);assertFalse(otherTitle[0].isEmpty());b.search.setText(name);});f.until(()->!b.loading&&b.shown==60);f.ui(()->{assertEquals(y[0],b.scroll.getScrollY());assertEquals(visible[0],discoverFirst(b));b.search.setText(other);});f.until(()->!b.loading&&b.shown==40);f.ui(()->{assertEquals(otherY[0],b.scroll.getScrollY());assertEquals(otherTitle[0],discoverFirst(b));});
  JSONObject picked=DataStore.objects(metas).stream().filter(v->("Explore "+v.optString("name")).equals(otherTitle[0])).findFirst().orElseThrow();if(!picked.optString("id").equals(id))f.cache(b.client,"meta/series/"+picked.optString("id")+".json",new JSONObject().put("meta",new JSONObject(picked.toString()).put("videos",episodes)));Instrumentation.ActivityMonitor monitor=f.test.addMonitor(DiscoverActivity.class.getName(),null,false);
  try{f.ui(()->{View card=AuditPhoneFixture.find(b.results,v->otherTitle[0].equals(v.getContentDescription()));assertNotNull(card);assertTrue(card.performClick());});f.clickWindow(Loc.t("Full page ›"));DiscoverActivity full=(DiscoverActivity)f.test.waitForMonitorWithTimeout(monitor,10000);assertNotNull("Preview opens the full detail activity",full);f.activities.add(full);f.until(()->!full.loading&&full.title!=null&&full.title.has("videos"));DiscoverActivity fullRestored=f.recreate(full);f.until(()->!fullRestored.loading&&fullRestored.title!=null&&fullRestored.title.has("videos"));f.ui(fullRestored::onBackPressed);f.idle();f.ui(()->{assertTrue(fullRestored.isFinishing()||fullRestored.isDestroyed());assertEquals(other,b.query);assertEquals(40,b.shown);assertEquals(otherY[0],b.scroll.getScrollY());assertEquals(otherTitle[0],discoverFirst(b));});}finally{f.test.removeMonitor(monitor);}
 }
 String discoverFirst(DiscoverActivity a){for(View v:AuditPhoneFixture.all(a.results,x->x.getContentDescription()!=null&&x.getContentDescription().toString().startsWith("Explore ")))if(AuditPhoneFixture.visible(v))return v.getContentDescription().toString();return "";}
}

final class AuditPhoneFixture implements AutoCloseable {
 final Instrumentation test=InstrumentationRegistry.getInstrumentation();final Context real=test.getTargetContext(),context;final File root;final DataStore previous=NoirApp.data,data;final DownloadStore previousDownloads=NoirApp.downloads;final boolean arabic=Loc.arabic;final JSONObject phoneCache=PhoneHarbor.phoneCache;final long phoneAt=PhoneHarbor.phoneAt,topTenAt=PhoneHarbor.topTenAt;final JSONArray topTen=PhoneHarbor.topTen;final String cacheProfile=PhoneStream.cacheProfile;
 final List<Activity> activities=new ArrayList<>();final List<File> cacheFiles=new ArrayList<>();final Set<String> preferences=new HashSet<>();
 AuditPhoneFixture()throws Exception{root=new File(real.getFilesDir(),"audit-n3-"+UUID.randomUUID());assertTrue(root.mkdirs());context=new ContextWrapper(real){@Override public Context getApplicationContext(){return this;}@Override public File getFilesDir(){return folder("files");}@Override public File getCacheDir(){return folder("cache");}@Override public File getExternalFilesDir(String type){return folder("external");}@Override public SharedPreferences getSharedPreferences(String name,int mode){String key=root.getName()+"-"+name;synchronized(preferences){preferences.add(key);}return real.getSharedPreferences(key,mode);}File folder(String name){File f=new File(root,name);f.mkdirs();return f;}};data=new DataStore(context);NoirApp.data=data;data.pref("language","en");data.pref("alerts",false);data.pref("experienceChosen",true);data.pref(PhonePreview.PREF,"off");File backups=new File(real.getExternalFilesDir(null),"backups");backups.mkdirs();File guard=new File(backups,"Noir-auto-"+root.getName()+".noirbackup");assertTrue(guard.createNewFile());cacheFiles.add(guard);NoirApp.downloads=new DownloadStore(data.context);PhoneHarbor.phoneCache=new JSONObject();PhoneHarbor.phoneAt=System.currentTimeMillis();PhoneStream.cacheProfile=data.profileId;PhoneHarbor.topTen=new JSONArray();PhoneHarbor.topTenAt=System.currentTimeMillis();Loc.use(data);}
 void ui(Runnable action){test.runOnMainSync(action);}
 void idle(){test.waitForIdleSync();ui(()->{});test.waitForIdleSync();}
 void until(BooleanSupplier condition)throws Exception{long end=SystemClock.elapsedRealtime()+10000;boolean[] ok={false};while(SystemClock.elapsedRealtime()<end){ui(()->ok[0]=condition.getAsBoolean());if(ok[0]){idle();return;}Thread.sleep(25);}fail("Timed out waiting for phone UI");}
 <A extends Activity>A launch(Class<A> kind){return launch(new Intent(real,kind));}
 @SuppressWarnings("unchecked") <A extends Activity>A launch(Intent intent){A a=(A)test.startActivitySync(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));activities.add(a);idle();return a;}
 @SuppressWarnings("unchecked") <A extends Activity>A recreate(A old)throws Exception{CountDownLatch resumed=new CountDownLatch(1);Activity[] next={null};Application app=(Application)real.getApplicationContext();Application.ActivityLifecycleCallbacks callbacks=new Application.ActivityLifecycleCallbacks(){public void onActivityCreated(Activity a,Bundle b){if(a!=old&&a.getClass()==old.getClass())next[0]=a;}public void onActivityResumed(Activity a){if(a==next[0])resumed.countDown();}public void onActivityStarted(Activity a){}public void onActivityPaused(Activity a){}public void onActivityStopped(Activity a){}public void onActivitySaveInstanceState(Activity a,Bundle b){}public void onActivityDestroyed(Activity a){}};app.registerActivityLifecycleCallbacks(callbacks);try{ui(old::recreate);assertTrue("Activity recreation resumed",resumed.await(15,TimeUnit.SECONDS));activities.add(next[0]);idle();return (A)next[0];}finally{app.unregisterActivityLifecycleCallbacks(callbacks);}}
 void cache(DiscoveryClient client,String path,JSONObject value)throws Exception{File file=new File(client.directory,DiscoveryClient.hash(path)+".json");assertFalse("Unique test cache must not overwrite existing metadata",file.exists());cacheFiles.add(file);DiscoveryClient.write(file,value.toString().getBytes(StandardCharsets.UTF_8));}
 void clickWindow(String text)throws Exception{long end=SystemClock.elapsedRealtime()+10000;while(SystemClock.elapsedRealtime()<end){android.view.accessibility.AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(root!=null)try{for(android.view.accessibility.AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(text))try{if(node.getText()!=null&&text.contentEquals(node.getText())&&node.isEnabled()&&node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK)){idle();return;}}finally{node.recycle();}}finally{root.recycle();}Thread.sleep(40);}fail("Dialog control not found: "+text);}
 static View find(View root,Predicate<View> match){if(match.test(root))return root;if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int n=0;n<g.getChildCount();n++){View v=find(g.getChildAt(n),match);if(v!=null)return v;}}return null;}
 static List<View> all(View root,Predicate<View> match){List<View> result=new ArrayList<>();collect(root,match,result);return result;}
 static void collect(View root,Predicate<View> match,List<View> result){if(match.test(root))result.add(root);if(root instanceof ViewGroup){ViewGroup g=(ViewGroup)root;for(int n=0;n<g.getChildCount();n++)collect(g.getChildAt(n),match,result);}}
 static void click(View root,String text){View v=find(root,x->x instanceof TextView&&((TextView)x).getText().toString().equals(Loc.t(text))&&x.hasOnClickListeners());assertNotNull("Visible control: "+text,v);assertTrue(v.performClick());}
 static void clickPrefix(View root,String text){View v=find(root,x->x instanceof TextView&&((TextView)x).getText().toString().startsWith(text)&&x.hasOnClickListeners());assertNotNull("Visible control: "+text,v);assertTrue(v.performClick());}
 static boolean visible(View v){Rect r=new Rect();return v.getGlobalVisibleRect(r)&&r.height()>8&&r.width()>8;}
 @Override public void close()throws Exception{try{ui(()->{for(Activity a:activities)if(!a.isDestroyed()){PhoneStream.cancel(a);a.finish();}});idle();data.network.shutdownNow();data.images.shutdownNow();assertTrue(data.network.awaitTermination(10,TimeUnit.SECONDS));assertTrue(data.images.awaitTermination(10,TimeUnit.SECONDS));data.flush();}finally{data.network.shutdownNow();data.images.shutdownNow();NoirApp.data=previous;NoirApp.downloads=previousDownloads;Loc.arabic=arabic;PhoneHarbor.phoneCache=phoneCache;PhoneHarbor.phoneAt=phoneAt;PhoneHarbor.topTen=topTen;PhoneHarbor.topTenAt=topTenAt;PhoneStream.cacheProfile=cacheProfile;NoirApp.scheduleSync(real);for(File file:cacheFiles){Files.deleteIfExists(file.toPath());Files.deleteIfExists(new File(file+".bak").toPath());Files.deleteIfExists(new File(file+".new").toPath());}synchronized(preferences){for(String name:preferences)real.deleteSharedPreferences(name);}remove(root);}}
 static void remove(File file)throws IOException{File[] children=file.listFiles();if(children!=null)for(File child:children)remove(child);if(file.exists()&&!file.delete())throw new IOException("Couldn't delete test fixture "+file);}
}
